```python
def sort4(a, b, c, d):
    """Return the four integers a, b, c, d as a tuple in non-decreasing order.
    """
    if a > b:
        a, b = (b, a)
    if c > d:
        c, d = (d, c)
    if a > d:
        a, d = (d, a)
    if b > d:
        b, d = (d, b)
    if b > c:
        b, c = (c, b)
    return (a, b, c, d)
